CREATE TABLE IF NOT EXISTS `submission_files` (`id` INT AUTO_INCREMENT PRIMARY KEY, `owner_id` INT NOT NULL, `quest_id` INT NOT NULL, `path` VARCHAR(255) NOT NULL, `mime` VARCHAR(32) NOT NULL DEFAULT 'image/png', `size` INT NOT NULL DEFAULT 0, `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT `uq_karya` UNIQUE (`owner_id`, `quest_id`), CONSTRAINT `fk_karya_owner` FOREIGN KEY (`owner_id`) REFERENCES `users` (`id`) ON DELETE CASCADE, CONSTRAINT `fk_karya_quest` FOREIGN KEY (`quest_id`) REFERENCES `quests` (`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
